static void *FakePickCtor(uint8_t *pick)
{
	memset(pick, 0, 0xE0);
	*(void **)(pick + 0xD0) = g_fakeWorld + 32;   /* a collector */
	return pick;
}
static void FakePickReset(uint8_t *pick) { *(int *)(pick + 0x60) = 0; *(float *)(pick + 0x64) = 1.0f; }
static void FakePickSetStartEnd(uint8_t *pick, const float *a, const float *b)
{
	memcpy(pick + 0x20, a, 12);
	memcpy(pick + 0x30, b, 12);
}
static bool FakePickHasHit(const uint8_t *pick) { return *(const int *)(pick + 0x60) != 0; }
static float FakePickFraction(const uint8_t *pick) { return *(const float *)(pick + 0x64); }
static uint8_t *FakeCellPick(uint8_t *cell, uint8_t *pick)
{
	(void)cell;
	const float *a = (const float *)(pick + 0x20), *b = (const float *)(pick + 0x30);
	float t = 2.0f;
	uint8_t *what = NULL;
	uint32_t layer = 0;
	float nrm[3] = { 0.0f, 0.0f, 0.0f };   /* the hit's surface normal, written at +0x70 as the game's pick has it (test 42) */
	float den = (b[2] - a[2]) - g_slopeK * ((b[0] - a[0]) * g_slopeD[0] + (b[1] - a[1]) * g_slopeD[1]);
	if (den != 0.0f || g_profileOn) {
		float tg = g_profileOn ? ProfileHit(a, b) : (g_groundZ + g_slopeK * ((a[0] - g_slopeO[0]) * g_slopeD[0] + (a[1] - g_slopeO[1]) * g_slopeD[1]) - a[2]) / den;
		float x = a[0] + (b[0] - a[0]) * tg, y = a[1] + (b[1] - a[1]) * tg;
		bool ground = !g_dropOn || (x - g_dropPoint[0]) * g_dropDir[0] + (y - g_dropPoint[1]) * g_dropDir[1] < 0.0f;
		if (g_shelfOn && g_shelfHeight < 0.0f) {   /* a hole (test 38): within the shelf's disc the ground is the shelf's plane, that far down */
			float h = PlayerHeading(), cx = PlayerPosition()[0] + sinf(h) * g_shelfAhead, cy = PlayerPosition()[1] + cosf(h) * g_shelfAhead;
			if (hypotf(x - cx, y - cy) < g_shelfRadius)
				ground = false;
		}
		if (g_kinkOn && (x - g_slopeO[0]) * g_slopeD[0] + (y - g_slopeO[1]) * g_slopeD[1] > g_kinkAt)
			ground = false;   /* past the kink: the flat's, below */
		if (tg >= 0.0f && tg <= 1.0f && ground) {
			t = tg;
			what = g_groundObj;
			layer = 13;
			float k = g_slopeK;   /* the ground's rise per unit along g_slopeD there: the profile's own where it's on */
			if (g_profileOn) {
				float u = ProfileU(x, y);
				k = ProfileZ(u + 0.5f) - ProfileZ(u - 0.5f);
			}
			float len = sqrtf(k * k + 1.0f);
			nrm[0] = -k * g_slopeD[0] / len;
			nrm[1] = -k * g_slopeD[1] / len;
			nrm[2] = 1.0f / len;
		}
	}
	if (g_dropOn && g_dropDepth > 0.0f && (den != 0.0f || g_profileOn)) {   /* the lower ground past the edge (test 42's landing) */
		float z0 = g_groundZ;
		g_groundZ = z0 - g_dropDepth;
		float tl = g_profileOn ? ProfileHit(a, b) : (g_groundZ + g_slopeK * ((a[0] - g_slopeO[0]) * g_slopeD[0] + (a[1] - g_slopeO[1]) * g_slopeD[1]) - a[2]) / den;
		g_groundZ = z0;
		float x = a[0] + (b[0] - a[0]) * tl, y = a[1] + (b[1] - a[1]) * tl;
		if (tl >= 0.0f && tl <= 1.0f && tl < t && (x - g_dropPoint[0]) * g_dropDir[0] + (y - g_dropPoint[1]) * g_dropDir[1] >= 0.0f) {
			t = tl;
			what = g_groundObj;
			layer = 13;
			float k = g_slopeK;
			if (g_profileOn) {
				float u = ProfileU(x, y);
				k = ProfileZ(u + 0.5f) - ProfileZ(u - 0.5f);
			}
			float len = sqrtf(k * k + 1.0f);
			nrm[0] = -k * g_slopeD[0] / len;
			nrm[1] = -k * g_slopeD[1] / len;
			nrm[2] = 1.0f / len;
		}
	}
	if (g_kinkOn && b[2] != a[2]) {
		float zk = g_groundZ + g_slopeK * g_kinkAt, tf = (zk - a[2]) / (b[2] - a[2]);
		float x = a[0] + (b[0] - a[0]) * tf, y = a[1] + (b[1] - a[1]) * tf;
		if (tf >= 0.0f && tf <= 1.0f && tf < t && (x - g_slopeO[0]) * g_slopeD[0] + (y - g_slopeO[1]) * g_slopeD[1] >= g_kinkAt) {
			t = tf;
			what = g_groundObj;
			layer = 13;
			nrm[0] = nrm[1] = 0.0f;   /* the flat past the kink */
			nrm[2] = 1.0f;
		}
	}
	for (int i = 0; i < g_pileCount; i++) {
		float z = g_groundZ + 5.0f * (float)(i + 1);
		if (b[2] == a[2])
			continue;
		float tp = (z - a[2]) / (b[2] - a[2]);
		float x = a[0] + (b[0] - a[0]) * tp, y = a[1] + (b[1] - a[1]) * tp;
		if (tp >= 0.0f && tp <= 1.0f && tp < t && hypotf(x - g_pilePoint[0], y - g_pilePoint[1]) < 60.0f) {
			t = tp;
			what = g_pileWhat;
			layer = g_pileLayer;
			nrm[0] = nrm[1] = 0.0f;
			nrm[2] = 1.0f;
		}
	}
	if (g_shelfOn && b[2] != a[2]) {
		float tp = (g_groundZ + g_shelfHeight - a[2]) / (b[2] - a[2]);
		float h = PlayerHeading(), cx = PlayerPosition()[0] + sinf(h) * g_shelfAhead, cy = PlayerPosition()[1] + cosf(h) * g_shelfAhead;
		float x = a[0] + (b[0] - a[0]) * tp, y = a[1] + (b[1] - a[1]) * tp;
		if (tp >= 0.0f && tp <= 1.0f && tp < t && hypotf(x - cx, y - cy) < g_shelfRadius) {
			t = tp;
			what = g_shelfWhat ? g_shelfWhat : g_shelfObj;
			layer = g_shelfLayer;
			nrm[0] = nrm[1] = 0.0f;   /* a disc's top (or a hole's floor) */
			nrm[2] = 1.0f;
		}
	}
	if (g_stepOn && b[2] != a[2]) {   /* 2026-11-06a: the truck's step (mode 14) */
		float tp = (g_groundZ + g_stepHeight - a[2]) / (b[2] - a[2]);
		float x = a[0] + (b[0] - a[0]) * tp, y = a[1] + (b[1] - a[1]) * tp;
		if (tp >= 0.0f && tp <= 1.0f && tp < t && hypotf(x - g_stepAt[0], y - g_stepAt[1]) < g_stepR) {
			t = tp;
			what = g_shelfObj;
			layer = 1;
			nrm[0] = nrm[1] = 0.0f;
			nrm[2] = 1.0f;
		}
	}
	for (int i = 0; i < 3; i++) {
		const FakePlane *w = &g_planes[i];
		if (!w->on)
			continue;
		float point[2] = { w->point[0], w->point[1] }, normal[2] = { w->normal[0], w->normal[1] };
		if (w->follow != 0.0f) {   /* resolved per cast: wherever the player is now, facing them */
			float h = PlayerHeading(), fx = sinf(h), fy = cosf(h);
			point[0] = PlayerPosition()[0] + fx * w->follow;
			point[1] = PlayerPosition()[1] + fy * w->follow;
			normal[0] = -fx;
			normal[1] = -fy;
		}
		float cot = w->slant > 0.0f ? 1.0f / tanf(w->slant / DEG) : 0.0f;   /* a slanted face sits further from the player the higher up: its surface is where the distance to the foot line equals the height over the ground times the cotangent */
		float da = (a[0] - point[0]) * normal[0] + (a[1] - point[1]) * normal[1] + (a[2] - g_groundZ) * cot;
		float db = (b[0] - point[0]) * normal[0] + (b[1] - point[1]) * normal[1] + (b[2] - g_groundZ) * cot;
		if (w->round && w->top > 0.0f) {   /* a log: where the ray enters the circle (s + R)^2 + (z - zc)^2 = R^2 across the line */
			float R = 0.5f * w->top, sa = da + R, za = a[2] - (g_groundZ + R), ds = db - da, dz = b[2] - a[2];
			float qa = ds * ds + dz * dz, qb = 2.0f * (sa * ds + za * dz), qc = sa * sa + za * za - R * R, disc = qb * qb - 4.0f * qa * qc;
			if (!(qa > 0.0f) || qc <= 0.0f || disc < 0.0f)
				continue;   /* no length, starting inside it, or passing it by */
			float tp = (-qb - sqrtf(disc)) / (2.0f * qa);
			if (!(tp >= 0.0f && tp <= 1.0f) || tp >= t)
				continue;
			if (w->halfWidth > 0.0f) {
				float x = a[0] + (b[0] - a[0]) * tp, y = a[1] + (b[1] - a[1]) * tp;
				if (fabsf((x - point[0]) * -normal[1] + (y - point[1]) * normal[0]) > w->halfWidth)
					continue;
			}
			t = tp;
			what = w->what ? w->what : g_wallObj;
			layer = w->layer;
			nrm[0] = normal[0] * (sa + ds * tp) / R;   /* the circle's outward normal at the hit */
			nrm[1] = normal[1] * (sa + ds * tp) / R;
			nrm[2] = (za + dz * tp) / R;
			continue;
		}
		if (!(da > 0.0f && db <= 0.0f))
			continue;
		float tp = da / (da - db), z = a[2] + (b[2] - a[2]) * tp;
		if (w->top > 0.0f && z > g_groundZ + w->top)
			continue;   /* over the top of it */
		if (w->bottom > 0.0f && z < g_groundZ + w->bottom)
			continue;   /* under it */
		if (w->halfWidth > 0.0f) {   /* a post: only so far along its line from point */
			float x = a[0] + (b[0] - a[0]) * tp, y = a[1] + (b[1] - a[1]) * tp;
			if (fabsf((x - point[0]) * -normal[1] + (y - point[1]) * normal[0]) > w->halfWidth)
				continue;
		}
		if (tp < t) {
			t = tp;
			what = w->what ? w->what : w->layer == 12 ? NULL : g_wallObj;
			layer = w->layer;
			/* Its normal facing the player: level for a vertical face, tilted back by the slant
			 * (slant s rises away at s from the horizontal: the surface's normal is the foot's
			 * normal times sin s, up cos s; the planner's §1.1.3). */
			float sn = w->slant > 0.0f ? sinf(w->slant / DEG) : 1.0f, cn = w->slant > 0.0f ? cosf(w->slant / DEG) : 0.0f;
			nrm[0] = normal[0] * sn;
			nrm[1] = normal[1] * sn;
			nrm[2] = cn;
		}
	}
	for (int i = 0; i < 3; i++) {   /* the planes' flat tops (mode 10's stage 2): a ray coming down onto one */
		const FakePlane *w = &g_planes[i];
		if (!w->on || g_planeTopDepth[i] <= 0.0f || w->top <= 0.0f || w->follow != 0.0f || w->round)
			continue;
		float zt = g_groundZ + w->top;
		if (!(a[2] > zt && b[2] <= zt))
			continue;
		float tp = (zt - a[2]) / (b[2] - a[2]), x = a[0] + (b[0] - a[0]) * tp, y = a[1] + (b[1] - a[1]) * tp;
		float sd = (x - w->point[0]) * w->normal[0] + (y - w->point[1]) * w->normal[1];   /* + in front of the face */
		if (sd <= 0.0f && sd >= -g_planeTopDepth[i] && tp < t) {
			t = tp;
			what = w->what ? w->what : g_wallObj;
			layer = w->layer;
			nrm[0] = nrm[1] = 0.0f;   /* a top */
			nrm[2] = 1.0f;
		}
	}
	*(int *)(pick + 0x60) = t <= 1.0f;
	*(float *)(pick + 0x64) = t <= 1.0f ? t : 1.0f;
	*(uint32_t *)(pick + 0xAC) = 0x12345600u | layer;   /* the layer in the low 7 bits */
	if (t > 1.0f || g_fakeNormalBad)
		nrm[0] = nrm[1] = nrm[2] = 0.0f;   /* no hit: zeros; mode 10's bad normal: zeros on hits too */
	memcpy(pick + 0x70, nrm, sizeof(nrm));   /* result.normal (bhkPickData +0x60 +0x10), read raw by the plugin since test 42 */
	*(void **)(pick + 0xC0) = g_fakeWorld;
	g_picks++;
	return what;
}

/* The player's animation graph (the 2026-11-01a build, LandSoft): PlayerCharacter's IAnimationGraphManagerHolder at +0x48
 * (CommonLibF4; BuildGame gives the player's class that base, mdisp 0x48, and the player a second vtable there), its slot 1
 * NotifyAnimationGraphImpl(const BSFixedString &). The fake graph counts what it gets by name and keeps the entry each
 * came as; the game's own landing cut (the speed times 0.35 for 0.45 s, test 42) moved here from LandingFrame: the hard
 * landings start it, the soft ones don't, as the game's graph does it (ledge.md 3). */
static uint8_t *NewString(const char *text);
#define GRAPH_NAMES 8
static const char *const g_graphNames[GRAPH_NAMES] = { "jumpLand", "jumpLandToRun", "jumpLandToWalk", "jumpImpactLand", "jumpImpactLandToRun", "jumpFall", "jumpRunningFall", "jumpWalkFall" };
enum { GN_LAND, GN_LAND_RUN, GN_LAND_WALK, GN_IMPACT, GN_IMPACT_RUN, GN_FALL, GN_FALL_RUN, GN_FALL_WALK };
static int g_graphGot[GRAPH_NAMES], g_graphOther, g_graphCuts;   /* what the graph got, by name; its cuts started */
static uint8_t *g_graphLast[GRAPH_NAMES];   /* the entry each name last came as */
static uint8_t *g_graphEntry[GRAPH_NAMES];  /* the fake game's own entries for them (made once) */
static uint8_t *g_poolEntry[4];             /* what FakeGetEntry made, in order */
static int g_poolCalls;
static uint32_t *g_holderMdisp;             /* the holder's mdisp in the player's class hierarchy (mode 4 moves it) */
static int g_graphUseGot;                   /* 2026-11-06a: dyn_ActivationAllowMovement, the item animation mod's use idle's event, as the graph got it */
static bool FakeGraphNotify(uint8_t *self, uint8_t *const *name)
{
	(void)self;
	const char *text = name && *name ? (const char *)(*name + 0x18) : "";
	for (int i = 0; i < GRAPH_NAMES; i++)
		if (_stricmp(text, g_graphNames[i]) == 0) {
			g_graphGot[i]++;
			g_graphLast[i] = *name;
			if (i == GN_IMPACT || i == GN_IMPACT_RUN) {
				g_landCutLeft = 0.45f;
				g_graphCuts++;
			}
			return true;
		}
	if (_stricmp(text, "dyn_ActivationAllowMovement") == 0) {
		g_graphUseGot++;
		return true;
	}
	g_graphOther++;
	return true;
}
static uint8_t *GraphEntry(int i)
{
	if (!g_graphEntry[i])
		g_graphEntry[i] = NewString(g_graphNames[i]);
	return g_graphEntry[i];
}
/* An event to the player's graph as the game sends it: through the holder's vtable (the plugin's wrapper when it's on). */
static bool GraphSend(int i)
{
	uint8_t *holder = g_player + 0x48, *entry = GraphEntry(i);
	bool (*notify)(uint8_t *, uint8_t *const *) = (bool (*)(uint8_t *, uint8_t *const *))(*(void ***)holder)[1];
	return notify(holder, &entry);
}
/* BSStringPool::GetEntry<char> (CommonLibF4's GetEntry_char, 2268729): a fresh entry each call, counted. */
static void FakeGetEntry(uint8_t **result, const char *text, bool caseSensitive)
{
	(void)caseSensitive;
	*result = NewString(text);
	if (g_poolCalls < 4)
		g_poolEntry[g_poolCalls] = *result;
	g_poolCalls++;
}
typedef struct { uint64_t id, rva; } LibPair49;
static int CmpLibPair49(const void *a, const void *b)
{
	uint64_t x = ((const LibPair49 *)a)->id, y = ((const LibPair49 *)b)->id;
	return x < y ? -1 : x > y;
}

/* F4SE's Address Library for 1.11.240, as the plugin reads it: a count, then {id, offset}
 * pairs sorted by id; the pick functions among some others. Since the 2026-11-01a build also
 * BSStringPool::GetEntry and the five game objects the plugin cross-checks (PlayerCamera,
 * TESDataHandler, PlayerControls, the two INI collections) at their RVAs, so it "matches this
 * game" for LandSoftNames=pool (not BSSoundHandle::SetVolume: the engine's sound stays off);
 * 600 ids as before, dummies for the rest. */
static void WriteAddressLibrary(void)
{
	struct { uint64_t id; void *f; } ours[] = {
		{ 2200263, (void *)FakeCellPick }, { 2230668, (void *)FakePickCtor }, { 2236622, (void *)FakePickSetStartEnd },
		{ 2277761, (void *)FakePickReset }, { 2277770, (void *)FakePickHasHit }, { 2277771, (void *)FakePickFraction },
		{ 2268729, (void *)FakeGetEntry },
	};
	const uint64_t cross[5][2] = { { 4796065, RVA_PLAYER_CAMERA }, { 4796135, RVA_DATA_HANDLER }, { 4799306, RVA_PLAYER_CONTROLS },
	                               { 2704108, RVA_INI_SETTINGS }, { 2703234, RVA_INI_PREF_SETTINGS } };
	static LibPair49 p[600];
	int n = 0;
	for (int i = 0; i < 7; i++) {
		p[n].id = ours[i].id;
		p[n++].rva = (uintptr_t)ours[i].f - g_base;
	}
	for (int i = 0; i < 5; i++) {
		p[n].id = cross[i][0];
		p[n++].rva = cross[i][1];
	}
	int taken = n;
	for (uint64_t id = 2200000; n < 600; id += 300) {
		bool same = false;
		for (int i = 0; i < taken; i++)
			same |= p[i].id == id;
		if (!same) {
			p[n].id = id;
			p[n++].rva = 0x1000 + id;
		}
	}
	qsort(p, (size_t)n, sizeof(p[0]), CmpLibPair49);
	FILE *f = fopen("version-1-11-240-0.bin", "wb");
	uint64_t count = (uint64_t)n;
	fwrite(&count, 8, 1, f);
	fwrite(p, sizeof(p[0]), (size_t)n, f);
	fclose(f);
}
/* The engine sound (mode 16, test 44's build): BSSoundHandle's SetFrequency, FadeTo and IsPlaying as
 * the plugin finds them through the Address Library (this in rcx: the handle the plugin builds per
 * call, { soundID, assumeSuccess 0, state 1 }), each call recorded against the loop whose instance id
 * it names, and true for one the harness's script "plays". g_sndRefuseOver1: SetFrequency over 1
 * returns false (a voice made with a frequency ratio of 1 at most). */
typedef struct { uint32_t soundID; uint8_t assumeSuccess, state, pad[2]; } FakeSoundHandle;
#define SND_LOOPS 11
static uint32_t g_sndPlaying[SND_LOOPS];   /* the instance ids playing (0: none): the script's StartEngineLoops plays them */
static uint32_t g_sndNextId = 1001;        /* the next instance id (fresh for every set, as the game's) */
static float g_sndFreq[SND_LOOPS];         /* each loop's frequency ratio as last taken (1 when played) */
static int g_sndAtt[SND_LOOPS];            /* its attenuation as last taken (0 when played) */
static int g_sndFreqCalls[SND_LOOPS], g_sndFadeCalls[SND_LOOPS], g_sndAskCalls, g_sndStrayCalls, g_sndBadHandles, g_sndOver1Tries;
/* Calls that change a loop's value by no more than the plugin's thresholds (PitchStep 0.003, LevelStep 30), not
 * counting each loop's first two of a set (the hand-over's) nor a loop coming out of or going into silence (10000). */
static int g_sndSmallSteps, g_sndSetCalls[SND_LOOPS];
static float g_sndFreqMax;                 /* the largest ratio asked for since it was cleared */
static bool g_sndRefuseOver1;
static int g_sndFirstFadeMs[SND_LOOPS];    /* each loop's first FadeTo of a set: its milliseconds (-1: none yet) */
/* Each loop's first call of a set (SetFrequency or FadeTo), over the run, and those made with CMB_SndDriven
 * already the set's generation: the hand-over's first frame must come before the answer, or the script
 * raises the loops' volume (the idle's, the nine's from 0) before their first level is set. */
static int g_sndFirstCalls, g_sndFirstLate;
static void SndFirstCall(int i)
{
	if (g_sndSetCalls[i])
		return;
	g_sndFirstCalls++;
	if (*(float *)(g_sndGlobalsFake[12] + 0x30) == *(float *)(g_sndGlobalsFake[11] + 0x30))
		g_sndFirstLate++;
}
/* Test 46: the game's audio side as test 45's tester disassembled it. SetVolume (message 13) carries the volume x 1000,
 * truncated, applied at once when it moved by 0.001 or more (the thousandths changed), clamped to [1e-5, 1]: the value
 * the script's Sound.SetInstanceVolume sets too. FadeTo (message 0x12): on its first tick the loop's attenuation as it
 * then is is the start, ms = max(ms, 100), a straight line in hundredths of a dB to the target; none cancels another,
 * each running message writing it every tick in the order they came (the newest's heard). The voice's gain is the
 * volume x 10^(-attenuation / 2000). SndAudioTick runs the messages once a frame, after the plugin's. */
#define SND_FADES 48
typedef struct { float start, target, secs, t; bool begun; } FakeFade;
static FakeFade g_sndFades[SND_LOOPS][SND_FADES];
static int g_sndFadeN[SND_LOOPS];
static float g_sndAttNow[SND_LOOPS];       /* each loop's attenuation as heard (FadeTo's ramps run), hundredths of a dB */
static int g_sndVolMilli[SND_LOOPS];       /* the volume the voice took, in thousandths (as the message carries it) */
static float g_sndVolAsked[SND_LOOPS];     /* the last SetVolume asked (the script's SetInstanceVolume at the start) */
static int g_sndVolCalls[SND_LOOPS];
static float g_sndVolFirst[SND_LOOPS];     /* each loop's first SetVolume of a set (-1: none yet) */
static float SndVoiceVolume(int i)
{
	float v = (float)g_sndVolMilli[i] / 1000.0f;
	return v < 1e-5f ? 1e-5f : v > 1.0f ? 1.0f : v;
}
static void SndPostVolume(int i, float volume)
{
	g_sndVolAsked[i] = volume;
	g_sndVolMilli[i] = (int)(volume * 1000.0f);   /* truncated; a change of its thousandths is applied at once */
}
static int SndLoopOf(const FakeSoundHandle *h)
{
	if (h->assumeSuccess != 0 || h->state != 1)
		g_sndBadHandles++;
	for (int i = 0; i < SND_LOOPS; i++)
		if (h->soundID && g_sndPlaying[i] == h->soundID)
			return i;
	return -1;
}
static bool FakeSoundSetFrequency(const FakeSoundHandle *h, float ratio)
{
	int i = SndLoopOf(h);
	if (i < 0) {
		g_sndStrayCalls++;
		return false;
	}
	g_sndFreqCalls[i]++;
	SndFirstCall(i);
	if (g_sndSetCalls[i]++ >= 2 && g_sndAtt[i] != 10000 && g_sndVolMilli[i] > 0 && fabsf(ratio - g_sndFreq[i]) <= 0.003f)
		g_sndSmallSteps++;   /* (a loop coming back from silence gets its pitch: FadeTo's 10000, or test 46's volume under the game's step) */
	if (ratio > g_sndFreqMax)
		g_sndFreqMax = ratio;
	if (ratio > 1.0f)
		g_sndOver1Tries++;
	if (g_sndRefuseOver1 && ratio > 1.0f)
		return false;
	g_sndFreq[i] = ratio;
	return true;
}
static bool FakeSoundFadeTo(const FakeSoundHandle *h, uint16_t attenuation, uint16_t ms)
{
	int i = SndLoopOf(h);
	if (i < 0) {
		g_sndStrayCalls++;
		return false;
	}
	g_sndFadeCalls[i]++;
	SndFirstCall(i);
	if (g_sndFirstFadeMs[i] < 0)
		g_sndFirstFadeMs[i] = ms;
	if (g_sndSetCalls[i]++ >= 2 && g_sndAtt[i] != 10000 && attenuation != 10000 && abs((int)attenuation - g_sndAtt[i]) <= 30)
		g_sndSmallSteps++;
	g_sndAtt[i] = attenuation;
	if (g_sndFadeN[i] == SND_FADES) {   /* (never at 48: a fade lasts 0.1 s at least, a frame 6 ms) */
		memmove(&g_sndFades[i][0], &g_sndFades[i][1], sizeof(FakeFade) * (SND_FADES - 1));
		g_sndFadeN[i]--;
	}
	FakeFade *f = &g_sndFades[i][g_sndFadeN[i]++];
	f->target = (float)attenuation;
	f->secs = (ms > 100 ? ms : 100) / 1000.0f;
	f->t = 0.0f;
	f->begun = false;
	return true;
}
static bool FakeSoundSetVolume(const FakeSoundHandle *h, float volume)
{
	int i = SndLoopOf(h);
	if (i < 0) {
		g_sndStrayCalls++;
		return false;
	}
	g_sndVolCalls[i]++;
	SndFirstCall(i);
	if (g_sndVolFirst[i] < 0.0f)
		g_sndVolFirst[i] = volume;
	if (g_sndSetCalls[i]++ >= 2 && fabsf(volume - g_sndVolAsked[i]) < 0.000999f && !(volume == 0.0f && g_sndVolAsked[i] > 0.0f))
		g_sndSmallSteps++;   /* under the game's step (a loop going silent from under it aside) */
	SndPostVolume(i, volume);
	return true;
}
/* The heard power sum against the asked (each loop's last SetVolume x its last FadeTo's target) while g_sndHoleOn:
 * the least, in dB, the time under -1 and -10 dB, and the family switches and hand-overs seen (the loudest asked loop
 * changing: on <-> off, or within a family; the default table's 0 idle, 1-6 on, 7-10 off). */
static bool g_sndHoleOn;
static float g_sndHoleMin, g_sndHoleUnder1, g_sndHoleUnder10, g_sndHoleAskedMax;
static int g_sndHoleFamily, g_sndHoleHand, g_sndHoleLast;
/* Test 47: the heard power sum (dB) each frame while g_sndHoleOn, and when the loudest loop went from the on family to
 * the off (ShiftFamily=1: an up-shift's clutch-in, 0.04 s on, halfway through FamilyTime's 0.08 s crossfade). */
#define SND_TRACK 4096
static float g_sndTrackT[SND_TRACK], g_sndTrackDb[SND_TRACK], g_sndHoleClock, g_sndUpAt[8];
static int g_sndTrackN, g_sndUpN;
/* 2026-11-06a: when the loudest loop went back from the off family to the on (an up-shift's gap over, ShiftTime after its
 * clutch-in), for the gap's length against g_sndUpAt. */
static float g_sndOnAt[8];
static int g_sndOnN;
/* Test 47: On2000's pitch and volume as the game took them, each frame while g_sndWatch (the cruise's wander) */
#define SND_WATCH 16384
static bool g_sndWatch;
static float g_sndWatchPitch[SND_WATCH], g_sndWatchVol[SND_WATCH], g_sndWatchT[SND_WATCH], g_sndWatchClock;
static int g_sndWatchN;
static void SndHoleReset(bool on)
{
	g_sndHoleOn = on;
	if (!on)
		return;   /* stopped: the figures kept */
	g_sndTrackN = g_sndUpN = g_sndOnN = 0;
	g_sndHoleClock = 0.0f;
	g_sndHoleMin = 100.0f;
	g_sndHoleUnder1 = g_sndHoleUnder10 = 0.0f;
	g_sndHoleAskedMax = -200.0f;
	g_sndHoleFamily = g_sndHoleHand = 0;
	g_sndHoleLast = -1;
}
static int SndFamilyOf(int i) { return i == 0 ? 0 : i <= 6 ? 1 : 2; }
static void SndAudioTick(float dt)
{
	if (g_sndWatch && g_sndWatchN < SND_WATCH) {
		g_sndWatchClock += dt;
		g_sndWatchT[g_sndWatchN] = g_sndWatchClock;
		g_sndWatchPitch[g_sndWatchN] = g_sndFreq[3];
		g_sndWatchVol[g_sndWatchN++] = SndVoiceVolume(3);
	}
	for (int i = 0; i < SND_LOOPS; i++) {
		int m = 0;
		for (int k = 0; k < g_sndFadeN[i]; k++) {
			FakeFade *f = &g_sndFades[i][k];
			if (!f->begun) {
				f->begun = true;
				f->start = g_sndAttNow[i];
			} else
				f->t += dt;
			float x = f->t / f->secs;
			g_sndAttNow[i] = f->start + (f->target - f->start) * (x < 1.0f ? x : 1.0f);
			if (x < 1.0f)
				g_sndFades[i][m++] = *f;
		}
		g_sndFadeN[i] = m;
	}
	if (!g_sndHoleOn)
		return;
	double heard = 0.0, asked = 0.0;
	int loud = -1;
	float loudGain = 0.0f;
	for (int i = 0; i < SND_LOOPS; i++) {
		if (!g_sndPlaying[i])
			continue;
		float gh = SndVoiceVolume(i) * powf(10.0f, -g_sndAttNow[i] / 2000.0f), ga = g_sndVolAsked[i] * powf(10.0f, -(float)g_sndAtt[i] / 2000.0f);
		heard += (double)gh * gh;
		asked += (double)ga * ga;
		if (ga > loudGain) {
			loudGain = ga;
			loud = i;
		}
	}
	if (asked < 1e-4)
		return;   /* asked under -40 dB: nothing to hear */
	float askedDb = (float)(10.0 * log10(asked)), d = (float)(10.0 * log10((heard + 1e-12) / asked));
	if (askedDb > g_sndHoleAskedMax)
		g_sndHoleAskedMax = askedDb;
	if (d < g_sndHoleMin)
		g_sndHoleMin = d;
	if (d < -1.0f)
		g_sndHoleUnder1 += dt;
	if (d < -10.0f)
		g_sndHoleUnder10 += dt;
	g_sndHoleClock += dt;
	if (g_sndTrackN < SND_TRACK) {
		g_sndTrackT[g_sndTrackN] = g_sndHoleClock;
		g_sndTrackDb[g_sndTrackN++] = (float)(10.0 * log10(heard + 1e-12));
	}
	if (loud >= 0 && g_sndHoleLast >= 0 && loud != g_sndHoleLast) {
		int a = SndFamilyOf(g_sndHoleLast), b = SndFamilyOf(loud);
		if (a == b && a)
			g_sndHoleHand++;
		else if (a && b)
			g_sndHoleFamily++;
		if (a == 1 && b == 2 && g_sndUpN < 8)
			g_sndUpAt[g_sndUpN++] = g_sndHoleClock;
		if (a == 2 && b == 1 && g_sndOnN < 8)
			g_sndOnAt[g_sndOnN++] = g_sndHoleClock;
	}
	if (loud >= 0)
		g_sndHoleLast = loud;
}
static bool FakeSoundIsPlaying(const FakeSoundHandle *h)
{
	g_sndAskCalls++;
	return SndLoopOf(h) >= 0;
}
static int SndCalls(void)
{
	int n = g_sndStrayCalls;
	for (int i = 0; i < SND_LOOPS; i++)
		n += g_sndFreqCalls[i] + g_sndFadeCalls[i] + g_sndVolCalls[i];
	return n;
}

/* An Address Library for mode 16, as F4SE's (a count, then {id, offset} pairs sorted by id): the
 * five IDs the plugin cross-checks at the game's RVAs (wrong: that one 8 off, -1 none), the three
 * sound functions at the fake's own (dataSound: SetFrequency's in the fake's data, not its code),
 * the pick functions as WriteAddressLibrary has them, padded with dummies; truncated: the last pair
 * cut off (not 8 + 16 x the count). */
typedef struct { uint64_t id, rva; } LibPair;
static int CmpLibPair(const void *a, const void *b)
{
	uint64_t x = ((const LibPair *)a)->id, y = ((const LibPair *)b)->id;
	return x < y ? -1 : x > y;
}
static void WriteSoundLibrary(const char *path, int wrong, bool dataSound, bool truncated)
{
	static LibPair p[700];
	int n = 0;
	const uint64_t cross[6][2] = { { 4796065, RVA_PLAYER_CAMERA }, { 4796135, RVA_DATA_HANDLER }, { 4799306, RVA_PLAYER_CONTROLS },
	                               { 2704108, RVA_INI_SETTINGS }, { 2703234, RVA_INI_PREF_SETTINGS }, { 2267057, RVA_SOUND_SET_VOLUME } };
	for (int i = 0; i < 6; i++) {   /* test 46: BSSoundHandle::SetVolume the sixth */
		p[n].id = cross[i][0];
		p[n++].rva = cross[i][1] + (i == wrong ? 8 : 0);
	}
	struct { uint64_t id; void *f; } funcs[] = {
		{ 2267059, (void *)FakeSoundSetFrequency }, { 2267074, (void *)FakeSoundFadeTo }, { 2267046, (void *)FakeSoundIsPlaying },
		{ 2200263, (void *)FakeCellPick }, { 2230668, (void *)FakePickCtor }, { 2236622, (void *)FakePickSetStartEnd },
		{ 2277761, (void *)FakePickReset }, { 2277770, (void *)FakePickHasHit }, { 2277771, (void *)FakePickFraction },
	};
	for (int i = 0; i < 9; i++) {
		p[n].id = funcs[i].id;
		p[n++].rva = (uintptr_t)funcs[i].f - g_base;
	}
	if (dataSound)
		p[6].rva = (uintptr_t)g_space + 0x100 - g_base;   /* SetFrequency's: in the image, in no code section */
	int ours = n;
	for (uint64_t id = 2200000; n < 600 + ours; id += 300) {
		bool taken = false;
		for (int i = 0; i < ours; i++)
			taken |= p[i].id == id;
		if (!taken) {
			p[n].id = id;
			p[n++].rva = 0x1000 + id;
		}
	}
	qsort(p, (size_t)n, sizeof(p[0]), CmpLibPair);
	FILE *f = fopen(path, "wb");
	uint64_t count = (uint64_t)n;
	fwrite(&count, 8, 1, f);
	fwrite(p, sizeof(p[0]), (size_t)(truncated ? n - 1 : n), f);
	fclose(f);
}
