		CHECK(g_picks == 0 || (WheelTravel(1) < 0.3f && WheelTravel(1) > -4.3f), "the rear within its droop (%+.1f: the frame sunk 4 and pitched 12 deg down, the line at the contact 8 below)", WheelTravel(1));
		g_shelfOn = false;
