	CHECK(RoomGlobal(4) == -18.0f && RoomGlobal(5) == -2.0f && LogLines(line) == 1, "ask 18 with the ground back: CMB_RoomAnswer %g (-18), CMB_RoomClear %g (-2), the line: \"%s\"", RoomGlobal(4), RoomGlobal(5), line);
