	CHECK(RoomGlobal(4) == 19.0f && LogLines(line) == 1 && LogLines(": rays work;") == worked + 1, "ask 19, past the 3 s: the test ray again by the old cadence, \"rays work\", room: \"%s\"", line);
	RewriteIni("RaysRetry=0", "RaysRetry=1");
