/* --- The engine sound (mode 16, test 44's build): the harness plays the controller script's side of
 * the hand-over (StartEngineLoops: eleven loops played, their ids into CMB_SndLoop01-11, CMB_SndGen
 * bumped last; StopEngineLoops: stopped, the ids 0, CMB_SndGen bumped) and reads CMB_SndDriven. The
 * expected numbers are test 45's model's (engine_model.py, its Python twin) on this ride: the
 * plugin's throttle from a tenth, +1/3 a second on W (at most Lead 0.2 over the measured speed),
 * -1/2 a second off, the fake moving at 900 x it (g_gameCurve), the plugin's speed a 0.2 s lag of
 * that (g_speedAlong); at 6 ms frames the twin's heard speed (its first pull's points drawn: the
 * shift at 2429, the launch at 1293) shifts to 2nd at 2393 rpm (the bike at 896 u/s, heard 540),
 * to 3rd at 2381 (900, heard 729), to 4th at 2316 (900, heard 900), 3.24, 4.59 and 5.84 s after W,
 * and cruises at 900 in 4th at 1937 rpm on On2000 (pitch 0.9685 x the wander's 1 + w), its level
 * 0.7 x (9.6 log2(1937/3000) + 5 x (0.45 - 1)) = -6.17 dB; at rest the idle at 0.7 x -17.2 =
 * -12.04 dB, the others silent. A 0.3 s tap at the cruise: no gear change (test 44's model: 4->3
 * at 813 u/s on the press again, back 0.7 s later); let go: in 4th till the coast's blip (4->3 at
 * 1667 rpm, 1.6 s on) and the clutch at the bike's 150 u/s (2202 rpm), none silent. W held from
 * rest with the fake no faster than 300, then 360 (g_topCap, test 45's review): no gear change, 1st
 * at 2043 and 2193 rpm (the slip from 1293), the heard speed the bike's (9f61073: 1->2 and back
 * every 2 s, the slip and HeardLead past ShiftLo with 2nd under DownRpm). The settings
 * of test 44 (HeardSpeed=0 and the rest) give test 44's numbers: 2nd at 556 u/s and 2365 rpm, 3rd
 * at 887 and 2918, 4th at 900 and 2344, the idle at 0.3 x -17.2 = -5.16 dB. The idle's first level comes over FirstFade's 400 ms (the script plays it
 * with no attenuation). The riding globals aren't asked (test 44's review: a rider with the MCM's
 * three sliders at 0): the last rides drive a set with them all 0, the steering off, the plugin's
 * own speed and the throttle read from it. Test 47: the throttle hand (at the cruise On2000's pitch
 * and level wander together, 0.30 dB per 1 %; none through a pull; since the 2026-10-31a build larger and held
 * softly under WanderMax: the twin, 32 s cruises over 150 seeds, the pitch's sd against its mean
 * 3.0 % (2.3-3.7, 2nd to 98th percentile; 27c 2.2), 1.17 % (0.87-1.55; 27c 1.07) in 4 s windows with
 * the trend taken out, the level 0.35 dB (0.26-0.47), the hand at most 5.6 % (4.8-5.9, never 6;
 * 27c's up to 9.3)) and each up-shift's throttle-off dip (the twin: -4.0 dB at the 0 dB ceiling,
 * 0.15 s under -3 dB; the pull's last, into the cruise, -6.2 at the 6 dB floor); the seven keys at
 * test 46's values give test 46's shifts and cruise. */
static float SndGlobal(int i) { return *(float *)(g_sndGlobalsFake[i] + 0x30); }
static void SndSet(int i, float v) { *(float *)(g_sndGlobalsFake[i] + 0x30) = v; }
static float SndGen(void) { return SndGlobal(11); }
static float SndDriven(void) { return SndGlobal(12); }
static void SndClearCounts(void)
{
	memset(g_sndFreqCalls, 0, sizeof(g_sndFreqCalls));
	memset(g_sndFadeCalls, 0, sizeof(g_sndFadeCalls));
	memset(g_sndVolCalls, 0, sizeof(g_sndVolCalls));
	g_sndAskCalls = g_sndStrayCalls = g_sndBadHandles = g_sndOver1Tries = g_sndSmallSteps = 0;
	g_sndFreqMax = 0.0f;
}
static float SndEngineVolume(void) { return *(float *)(g_engineVolumeFake + 0x30) / 100.0f; }
static void ScriptStartLoops(void)
{
	for (int i = 0; i < SND_LOOPS; i++) {
		g_sndPlaying[i] = g_sndNextId++;
		g_sndFreq[i] = 1.0f;
		g_sndAtt[i] = 0;
		g_sndSetCalls[i] = 0;
		g_sndFirstFadeMs[i] = -1;
		g_sndFadeN[i] = 0;
		g_sndAttNow[i] = 0.0f;
		g_sndVolFirst[i] = -1.0f;
		SndPostVolume(i, i == 0 ? SndEngineVolume() : 0.0f);   /* the script's: the idle at the engine volume (StartEngineLoops' UpdateEngineSound(0)), the cruise at 0 x it, the nine at 0 */
		SndSet(i, (float)g_sndPlaying[i]);
	}
	SndClearCounts();
	SndSet(11, SndGen() + 1.0f);
}
static void ScriptStopLoops(void)
{
	memset(g_sndPlaying, 0, sizeof(g_sndPlaying));
	for (int i = 0; i < SND_LOOPS; i++)
		SndSet(i, 0.0f);
	SndSet(11, SndGen() + 1.0f);
}
static void SndGetOn(void)
{
	SetLive(45.0f);
	SetCamera(300.0f);
	SetTilt(30.0f);
	RunFrames(600);   /* a tick or more: the ride's start (its settings read again) */
}
static void SndGetOff(void)
{
	Keys(0.0f, 0.0f);
	RunFrames(2500);   /* rolled to a stop */
	ScriptStopLoops();
	SetLive(0.0f);
	SetCamera(0.0f);
	SetTilt(0.0f);
	RunFrames(400);
}
static void SndOffer(void)
{
	ScriptStartLoops();
	OneFrame();
	OneFrame();
}
static bool SndSilent(int i) { return g_sndAtt[i] == 10000 || g_sndVolMilli[i] <= 0; }   /* FadeTo(10000), or a volume under the game's step (test 46) */
static int SndSilentOthers(int except)   /* the loops silent but one */
{
	int n = 0;
	for (int i = 0; i < SND_LOOPS; i++)
		n += i != except && SndSilent(i);
	return n;
}
/* The gear lines ("sound: gear N at V u/s, R rpm[, heard H u/s[, a blip]][ (clutch in)]") after the
 * log's last line holding marker; heard -1 where the line has none, flags 1 a blip, 2 the clutch in. */
static float g_sndHeard[16];
static int g_sndGearFlags[16];
static int SndGearLines(const char *marker, int *gear, float *v, float *rpm, int max)
{
	static char line[4096];
	FILE *f = OpenLog();
	int n = 0;
	if (!f)
		return 0;
	while (fgets(line, sizeof(line), f)) {
		if (strstr(line, marker))
			n = 0;
		const char *at = strstr(line, "sound: gear ");
		if (at && n < max && n < 16 && sscanf(at, "sound: gear %d at %f u/s, %f rpm", &gear[n], &v[n], &rpm[n]) == 3) {
			const char *h = strstr(at, " rpm, heard ");
			g_sndHeard[n] = h && sscanf(h, " rpm, heard %f", &g_sndHeard[n]) == 1 ? g_sndHeard[n] : -1.0f;
			g_sndGearFlags[n] = (strstr(at, ", a blip") ? 1 : 0) | (strstr(at, "(clutch in)") ? 2 : 0);
			n++;
		}
	}
	fclose(f);
	return n;
}
static void SndFullThrottle(int ms)
{
	Keys(0.0f, 1.0f);
	RunFrames(ms);
}
/* Test 47: the up-shifts' dips in the pull just tracked (SndHoleReset): at each clutch-in (0.04 s before the loudest loop
 * went from the on family to the off), the heard level's least over the 0.6 s from it against its mean 0.25-0.05 s
 * before, and the time under 3 dB below that mean (the twin's measure, tools/sound/engine_model.py's ShiftDip). */
static int SndDips(float *depth, float *under3, int max)
{
	int n = 0;
	for (int k = 0; k < g_sndUpN && n < max; k++) {
		float t0 = g_sndUpAt[k] - 0.04f, least = 100.0f, under = 0.0f;
		double sum = 0.0;
		int m = 0;
		for (int i = 0; i < g_sndTrackN; i++)
			if (g_sndTrackT[i] >= t0 - 0.25f && g_sndTrackT[i] < t0 - 0.05f) {
				sum += g_sndTrackDb[i];
				m++;
			}
		if (!m)
			continue;
		float ref = (float)(sum / m);
		for (int i = 1; i < g_sndTrackN; i++)
			if (g_sndTrackT[i] >= t0 && g_sndTrackT[i] < t0 + 0.6f) {
				float d = g_sndTrackDb[i] - ref;
				if (d < least)
					least = d;
				if (d < -3.0f)
					under += g_sndTrackT[i] - g_sndTrackT[i - 1];
			}
		depth[n] = least;
		under3[n++] = under;
	}
	return n;
}
/* Test 47: the wander's size over the cruise just watched (g_sndWatch): in 4 s windows, the trend taken out, the sd of
 * On2000's pitch (in % of its mean) and of its level (dB) as the game took them, their means over the windows, and the
 * level's slope against the pitch (dB per 1 %, over all the windows). The windows' count. */
static int SndWanderWindows(float *pitchSd, float *levelSd, float *slope)
{
	int windows = 0, i0 = 0;
	double sp = 0.0, sl = 0.0, num = 0.0, den = 0.0;
	while (i0 < g_sndWatchN) {
		int i1 = i0;
		while (i1 < g_sndWatchN && g_sndWatchT[i1] < g_sndWatchT[i0] + 4.0f)
			i1++;
		if (i1 >= g_sndWatchN)
			break;   /* a window cut short: left out */
		int n = i1 - i0;
		double tm = 0.0, pm = 0.0, lm = 0.0;
		for (int i = i0; i < i1; i++) {
			tm += g_sndWatchT[i];
			pm += g_sndWatchPitch[i];
			lm += 20.0 * log10(g_sndWatchVol[i]);
		}
		tm /= n;
		pm /= n;
		lm /= n;
		double stt = 0.0, stp = 0.0, stl = 0.0;
		for (int i = i0; i < i1; i++) {
			double t = g_sndWatchT[i] - tm, p = 100.0 * (g_sndWatchPitch[i] / pm - 1.0), l = 20.0 * log10(g_sndWatchVol[i]) - lm;
			stt += t * t;
			stp += t * p;
			stl += t * l;
		}
		double bp = stp / stt, bl = stl / stt, rp2 = 0.0, rl2 = 0.0;
		for (int i = i0; i < i1; i++) {
			double t = g_sndWatchT[i] - tm, rp = 100.0 * (g_sndWatchPitch[i] / pm - 1.0) - bp * t, rl = 20.0 * log10(g_sndWatchVol[i]) - lm - bl * t;
			rp2 += rp * rp;
			rl2 += rl * rl;
			num += rp * rl;
			den += rp * rp;
		}
		sp += sqrt(rp2 / (n - 1));
		sl += sqrt(rl2 / (n - 1));
		windows++;
		i0 = i1;
	}
	*pitchSd = windows ? (float)(sp / windows) : 0.0f;
	*levelSd = windows ? (float)(sl / windows) : 0.0f;
	*slope = den > 0.0 ? (float)(num / den) : 0.0f;
	return windows;
}
/* the 2026-10-31a build: over the whole cruise watched, On2000's pitch against its own mean: the sd and the largest |deviation| (%). */
static void SndWanderWhole(float *sd, float *most)
{
	double pm = 0.0, s2 = 0.0, m = 0.0;
	for (int i = 0; i < g_sndWatchN; i++)
		pm += g_sndWatchPitch[i];
	pm = g_sndWatchN ? pm / g_sndWatchN : 1.0;
	for (int i = 0; i < g_sndWatchN; i++) {
		double d = 100.0 * (g_sndWatchPitch[i] / pm - 1.0);
		s2 += d * d;
		if (fabs(d) > m)
			m = fabs(d);
	}
	*sd = g_sndWatchN ? (float)sqrt(s2 / g_sndWatchN) : 0.0f;
	*most = (float)m;
}
/* Test 47: the trace lines' " hand " (the wander, %) after the log's last line holding marker, in gears up to maxGear:
 * the largest size, and how many such lines. */
static float SndHandMax(const char *marker, int maxGear, int *lines)
{
	static char line[4096];
	FILE *f = OpenLog();
	float most = 0.0f;
	int n = 0;
	if (f) {
		while (fgets(line, sizeof(line), f)) {
			if (strstr(line, marker))
				most = 0.0f, n = 0;
			const char *e = strstr(line, "| engine g"), *h = e ? strstr(e, " hand ") : NULL;
			int g;
			float v;
			if (h && sscanf(e, "| engine g%d", &g) == 1 && g <= maxGear && sscanf(h, " hand %f", &v) == 1) {
				if (fabsf(v) > most)
					most = fabsf(v);
				n++;
			}
		}
		fclose(f);
	}
	*lines = n;
	return most;
}

