/* The 2026-11-01a build's stops: every gear line ("sound: gear N at V u/s, R rpm[, heard H u/s[, a blip]][ (clutch in)]") after the
 * log's last line holding marker: their count (all of them), the last one's gear, and those after the first skip (16 at most)
 * with their times (s of the day, the log's own stamp) in g_stop*. */
#define SND_STOP_MAX 16
static int g_stopGear[SND_STOP_MAX], g_stopFlags[SND_STOP_MAX], g_stopN, g_stopLastGear;
static float g_stopV[SND_STOP_MAX], g_stopRpm[SND_STOP_MAX];
static double g_stopT[SND_STOP_MAX];
static int SndGearsAfter(const char *marker, int skip)
{
	static char line[4096];
	FILE *f = OpenLog();
	int n = 0;
	bool seen = false;
	g_stopN = 0;
	g_stopLastGear = 0;
	if (!f)
		return 0;
	while (fgets(line, sizeof(line), f)) {
		if (strstr(line, marker)) {
			n = g_stopN = g_stopLastGear = 0;
			seen = true;
		}
		const char *at = strstr(line, "sound: gear ");
		unsigned h, m, sec, ms;
		int g;
		float v, r;
		if (!at || sscanf(at, "sound: gear %d at %f u/s, %f rpm", &g, &v, &r) != 3)
			continue;
		g_stopLastGear = g;
		if (n++ < skip || g_stopN >= SND_STOP_MAX)
			continue;
		g_stopGear[g_stopN] = g;
		g_stopV[g_stopN] = v;
		g_stopRpm[g_stopN] = r;
		g_stopFlags[g_stopN] = (strstr(at, ", a blip") ? 1 : 0) | (strstr(at, "(clutch in)") ? 2 : 0);
		g_stopT[g_stopN++] = sscanf(line, "%u:%u:%u.%u", &h, &m, &sec, &ms) == 4 ? h * 3600.0 + m * 60.0 + sec + ms / 1000.0 : 0.0;
	}
	fclose(f);
	if (!seen)
		g_stopN = 0;
	return seen ? n : -1;   /* -1: no such marker */
}
static double SndNowOfDay(void)
{
	SYSTEMTIME t;
	GetLocalTime(&t);
	return t.wHour * 3600.0 + t.wMinute * 60.0 + t.wSecond + t.wMilliseconds / 1000.0;
}
/* The fake's speed through the plugin's 0.2 s smoothing (its speed along), and when that last went under ClutchSpeed's 150. */
static float g_sndLagV;
static double g_sndUnder150At = -1.0;
static void SndLagFrame(float dt)
{
	FakeGameFrame(dt);
	float was = g_sndLagV;
	g_sndLagV += (g_fakeSpeedNow - g_sndLagV) * (1.0f - expf(-dt / 0.2f));
	if (was >= 150.0f && g_sndLagV < 150.0f)
		g_sndUnder150At = SndNowOfDay();
}
static void SndSpace(bool down)   /* the brake key, Space (VK 0x20), through CMB_TestKeyState */
{
	g_testVk = 0x20;
	g_testKeyHeld = down;
}
/* A stop's lines in g_stop*: n down-shifts from 4th, each a blip, at rpm[i] (+-120) with the bike at v[i] (+-60; v NULL: unchecked), at
 * least StopGap - 0.02 apart; then the clutch in 1st between clutchLo and clutchHi rpm with the bike under bikeHi, gapLo to gapHi s
 * after the last down-shift, and nothing more. Its words into why. */
static bool SndStopLines(int n, const float *rpm, const float *v, float clutchLo, float clutchHi, float bikeHi, float gapLo, float gapHi, char *why, size_t size)
{
	size_t len = (size_t)snprintf(why, size, "%d line(s):", g_stopN);
	bool ok = g_stopN == n + 1 && g_stopGear[0] == 3;
	for (int i = 0; i < g_stopN && len + 96 < size; i++) {
		double gap = i ? g_stopT[i] - g_stopT[i - 1] : 0.0;
		len += (size_t)snprintf(why + len, size - len, " %d at %.0f rpm, %.0f u/s%s%s", g_stopGear[i], g_stopRpm[i], g_stopV[i], g_stopFlags[i] & 1 ? ", a blip" : "",
		                        g_stopFlags[i] & 2 ? " (clutch in)" : "");
		len += i ? (size_t)snprintf(why + len, size - len, " +%.2f s;", gap) : (size_t)snprintf(why + len, size - len, ";");
		if (i < n)
			ok &= g_stopGear[i] == 3 - i && (g_stopFlags[i] & 1) && !(g_stopFlags[i] & 2) && fabsf(g_stopRpm[i] - rpm[i]) < 120.0f &&
			      (!v || fabsf(g_stopV[i] - v[i]) < 60.0f) && (i == 0 || gap >= 0.38);
		else if (i == n)
			ok &= g_stopGear[i] == 1 && (g_stopFlags[i] & 2) && g_stopRpm[i] > clutchLo && g_stopRpm[i] < clutchHi && g_stopV[i] < bikeHi && gap >= gapLo && gap <= gapHi;
	}
	return ok;
}

/* The 2026-11-02a build (test 48: "fully quiet when it stops"): the engine's summed gain, the square root of the sum of the
 * playing loops' squared volumes over the engine volume (the twin's sqrt(sum of gains^2)), each frame after the game's
 * audio tick while g_sndSumOn: its least since SndSumStart, and its least and most from g_sndSumFrom s on. */
static bool g_sndSumOn;
static float g_sndSumClock, g_sndSumFrom, g_sndSumLeast, g_sndSumLeastAt, g_sndSumLo, g_sndSumHi;
static void SndSumTick(float dt)
{
	SndAudioTick(dt);
	if (!g_sndSumOn)
		return;
	g_sndSumClock += dt;
	double sum = 0.0;
	for (int i = 0; i < SND_LOOPS; i++)
		if (g_sndPlaying[i])
			sum += (double)SndVoiceVolume(i) * SndVoiceVolume(i);
	float ev = SndEngineVolume(), g = ev > 0.0f ? (float)sqrt(sum) / ev : 0.0f;
	if (g < g_sndSumLeast) {
		g_sndSumLeast = g;
		g_sndSumLeastAt = g_sndSumClock;
	}
	if (g_sndSumClock >= g_sndSumFrom) {
		g_sndSumLo = fminf(g_sndSumLo, g);
		g_sndSumHi = fmaxf(g_sndSumHi, g);
	}
}
static void SndSumStart(float from)
{
	g_sndSumClock = 0.0f;
	g_sndSumFrom = from;
	g_sndSumLeast = g_sndSumLo = 100.0f;
	g_sndSumHi = -1.0f;
	g_sndSumLeastAt = -1.0f;
	g_sndSumOn = true;
	g_afterTask = SndSumTick;
}
static void SndSumStop(void)
{
	g_sndSumOn = false;
	g_afterTask = SndAudioTick;
}

/* 2026-11-06a (test 49's launch rev): each frame after the game's audio tick while g_afterTask is SndLaunchTick, the heard
 * rpm (the loudest loop's pitch x the rpm it was made at: the default table's idle 860, on 1400-3300, off 1400-2800) and
 * the summed level (the loops' root sum of squares, the engine volume in it). SndLaunchFigures: from the engine's press
 * (the first frame over 900 rpm) the most in the first `most` s and the rpm and the summed level at +0.5 s. */
#define SND_LAUNCH 2048
static float g_sndLaunchT[SND_LAUNCH], g_sndLaunchRpm[SND_LAUNCH], g_sndLaunchSum[SND_LAUNCH], g_sndLaunchClock;
static int g_sndLaunchN;
static void SndLaunchTick(float dt)
{
	static const float base[SND_LOOPS] = { 860.0f, 1400.0f, 1700.0f, 2000.0f, 2400.0f, 2800.0f, 3300.0f, 1400.0f, 1800.0f, 2300.0f, 2800.0f };
	SndAudioTick(dt);
	g_sndLaunchClock += dt;
	if (g_sndLaunchN >= SND_LAUNCH)
		return;
	int loud = -1;
	float most = 0.0f;
	double sum = 0.0;
	for (int i = 0; i < SND_LOOPS; i++) {
		if (!g_sndPlaying[i])
			continue;
		float v = SndVoiceVolume(i);
		sum += (double)v * v;
		if (v > most) {
			most = v;
			loud = i;
		}
	}
	g_sndLaunchT[g_sndLaunchN] = g_sndLaunchClock;
	g_sndLaunchRpm[g_sndLaunchN] = loud >= 0 ? g_sndFreq[loud] * base[loud] : 0.0f;
	g_sndLaunchSum[g_sndLaunchN++] = (float)sqrt(sum);
}
static void SndLaunchStart(void)
{
	g_sndLaunchN = 0;
	g_sndLaunchClock = 0.0f;
	g_afterTask = SndLaunchTick;
}
/* 2026-11-06a: each up-shift's gap in the pull just tracked (SndHoleReset): from the loudest loop's switch to the off family
 * (the clutch-in) to its first switch back to the on (the gap's end); the pairs found, their least and most, as text. */
static int SndShiftGaps(float *lo, float *hi, char *text, size_t size)
{
	int n = 0;
	size_t len = 0;
	*lo = 9.0f;
	*hi = 0.0f;
	text[0] = 0;
	for (int k = 0; k < g_sndUpN; k++)
		for (int j = 0; j < g_sndOnN; j++)
			if (g_sndOnAt[j] > g_sndUpAt[k]) {
				float gap = g_sndOnAt[j] - g_sndUpAt[k];
				*lo = fminf(*lo, gap);
				*hi = fmaxf(*hi, gap);
				n++;
				if (len + 16 < size)
					len += (size_t)snprintf(text + len, size - len, " %.3f", gap);
				break;
			}
	return n;
}
static void SndLaunchFigures(float window, float *most, float *at05, float *sum05, float *pressAt)
{
	g_afterTask = SndAudioTick;
	int i0 = 0;
	while (i0 < g_sndLaunchN && g_sndLaunchRpm[i0] <= 900.0f)
		i0++;
	*most = *at05 = *sum05 = 0.0f;
	*pressAt = i0 < g_sndLaunchN ? g_sndLaunchT[i0] : -1.0f;
	if (i0 >= g_sndLaunchN)
		return;
	float t0 = g_sndLaunchT[i0];
	bool got = false;
	for (int i = i0; i < g_sndLaunchN; i++) {
		float t = g_sndLaunchT[i] - t0;
		if (t <= window && g_sndLaunchRpm[i] > *most)
			*most = g_sndLaunchRpm[i];
		if (!got && t >= 0.5f) {
			got = true;
			*at05 = g_sndLaunchRpm[i];
			*sum05 = g_sndLaunchSum[i];
		}
	}
}

