	float dz = ViewNodeD(0)[2];
	bool up = fabsf(dzWas - (fakeEye[2] - 128.0f)) < 0.05f && fabsf(dz - (fakeEye[2] - 118.0f)) < 0.05f && LogLines(nowText) == now0 + 1;
	*fwdG = 45.0f;
